-- Hướng dẫn liệu trình: Chỉ định · Chỉ định mở rộng & cơ chế · Hướng dẫn tư vấn
-- (tab KTV, sheet "AI QUY TRÌNH LIỆU TRÌNH MOANA 2026", 06/11/2026) + tìm kiếm liệu trình trong ô tìm kiếm chung.

create table if not exists public.service_guides (
  service_id uuid primary key references public.services(id) on delete cascade,
  indication text,
  indication_ext text,
  consult_guide text,
  updated_at timestamptz not null default now()
);
alter table public.service_guides enable row level security;
create policy "staff read" on public.service_guides for select using ((select public.is_staff()));
create policy "management write" on public.service_guides for all
  using ((select public.has_role('owner','manager'))) with check ((select public.has_role('owner','manager')));

insert into public.service_guides (service_id, indication, indication_ext, consult_guide)
select (r->>0)::uuid, nullif(r->>1, ''), nullif(r->>2, ''), nullif(r->>3, '')
  from jsonb_array_elements('[["9fa8c463-15b8-41b9-af87-f2e099e2b6dc", "Chăm sóc da cơ bản\nPhù hợp làm thư giãn\nKhách mới muốn thư giãn massage hoặc duy trì đều đặn\nLàn da không có hoặc có ít mụn", "• Cơ chế: làm sạch 2 bước (micellar HA Dermedic + SRM Christina) → tẩy tế bào chết Dermalogica → xông hơi mở lỗ chân lông → massage Recovery Touch giúp lưu thông máu & bạch huyết → mặt nạ bột kháng viêm hút dầu, làm dịu → Simildiet Post Treatment khoá ẩm → Neoretin/Heliocare chống nắng & chống oxy hoá.\n• Chỉ định thêm: da dầu bít tắc nhẹ, mụn đầu đen, da xỉn do bụi bẩn, căng thẳng mệt mỏi, mất ngủ; dùng duy trì giữa các đợt treatment.\n• Hạn chế: da đang mụn viêm nhiều (chuyển Acne Tweezer/Enzyme Power).", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: massage 16 đường cơ với Comfortzone Recovery Touch giúp thư giãn sâu, lưu thông máu; mặt nạ bột kháng viêm hút dầu, làm dịu – da sạch thoáng, ráo dầu, tươi tắn ngay sau buổi.\n③ Uy tín: massage Comfortzone (Ý), tẩy trang Dermedic (Ba Lan), phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha – dược mỹ phẩm Châu Âu ở các bước chính."], ["fed5dda1-6e04-4180-abe6-321a6ebec39c", "Chăm sóc da cơ bản\nPhù hợp đối tượng khách hàng có tuổi muốn thư giãn healing\nKhách mới muốn trải nghiệm cảm nhận thư giãn \nLàn da không có quá nhiều vấn đề", "• Cơ chế: như Purifying nhưng nhấn vào cấp ẩm – micellar Hydrain3 chứa HA giữ nước ngay từ bước làm sạch, massage chậm healing, mặt nạ + serum phục hồi, kem Simildiet khoá ẩm.\n• Chỉ định thêm: da khô, mất nước, bong tróc nhẹ do thời tiết/máy lạnh; da lão hoá sớm nếp nhăn mất nước; khách stress cần thư giãn sâu.\n• Hạn chế: da dầu mụn viêm.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: cấp ẩm từ bước làm sạch với Hydrain3 (HA) + massage healing chậm, sâu – da mềm căng, hết khô ráp, cơ thể thư giãn, ngủ ngon hơn.\n③ Uy tín: massage Comfortzone (Ý), tẩy trang Dermedic Hydrain3 (Ba Lan), phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["6d05544f-e4b7-40ae-baad-7c42056cbc9e", "Lấy nhân mụn chuyên sâu\nCó các pp hỗ trợ làm dịu da sau lấy mụn\nPhù hợp cho những nền da nhiều mụn, sau peel", "• Cơ chế: xông hơi làm mềm nhân mụn → lấy nhân chuyên sâu bằng Acne Tweezer → mặt nạ bột kháng viêm làm dịu, se lỗ chân lông → Simildiet Post Treatment phục hồi, giảm thâm đỏ sau nặn → KCN.\n• Chỉ định thêm: mụn đầu đen/đầu trắng, mụn ẩn dày đặc, da bít tắc sau thời gian dùng mỹ phẩm sai, giai đoạn đẩy mụn sau peel/treatment.\n• Hạn chế: mụn bọc, mụn mủ đang sưng đau lan rộng (kết hợp Acne Spot Meso/Light Therapy trước).", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: lấy sạch nhân mụn chuyên sâu bằng kỹ thuật Acne Tweezer, sau đó đắp mặt nạ bột kháng viêm làm dịu, se lỗ chân lông – da thông thoáng, giảm sần mà không sưng đau, không thâm.\n③ Uy tín: tẩy trang Dermedic (Ba Lan), phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["3e6274d7-45d7-4543-bac2-c80bdf8b6ec3", "Làm sáng da không xâm lấn\nPP điện di ion vitamin C giúp các tinh thể vit C đi sâu vào da và làm da sáng dần lên\nLưu ý chỉ sử dụng cho những nền da không có mụn\nLiệu trình có massage thư giãn nâng cơ", "• Cơ chế: tẩy da chết làm mỏng lớp sừng → điện di ion/RF đưa CPU Arbutin + vitamin C xuống sâu ức chế men tyrosinase (giảm tạo melanin) → massage nâng cơ → mặt nạ Mona Frema làm dịu, khoá dưỡng chất.\n• Chỉ định thêm: da xỉn màu, không đều màu, thâm nâu nhẹ sau mụn, da sạm do nắng, chuẩn bị trước sự kiện.\n• Hạn chế: da đang mụn viêm, có thiết bị kim loại cấy ghép/máy tạo nhịp tim (với điện di), mang thai.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: điện di ion đưa tinh thể vitamin C + Arbutin xuống sâu, ức chế sắc tố – da sáng hồng ngay sau buổi, không kim, không bong, đi làm được luôn.\n③ Uy tín: tẩy trang Dermedic (Ba Lan), phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["a9f1430e-d9e3-4de2-90fe-abc2a5de44dc", "Làm dịu da , chứa các thành phần chống oxy hoá mạnh mẽ\nCấp ẩm trở lại cho nền da mất nước\nTạo hiệu ứng căng bóng cho bề mặt da\nLiệu trình có massage thư giãn nâng cơ", "• Cơ chế: điện di đưa hoạt chất chống oxy hoá + cấp ẩm vào da → làm dịu đỏ, cấp nước cho da thiếu ẩm → massage nâng cơ → mặt nạ Mona Frema khoá ẩm, hiệu ứng căng bóng.\n• Chỉ định thêm: da nhạy cảm, ửng đỏ nhẹ do thời tiết, da mất nước sau đi nắng/đi biển, da sau laser/peel đã hết bong (phục hồi duy trì).\n• Hạn chế: mụn viêm nhiều.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: điện di hoạt chất chống oxy hoá + cấp ẩm, kết hợp massage nâng cơ – làm dịu da đỏ rát, bù nước cho da mất nước, tạo hiệu ứng căng bóng tức thì.\n③ Uy tín: tẩy trang Dermedic (Ba Lan), phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["855e0cc1-3174-47a6-bb8d-92374f32f6b8", "Thanh lọc và cân bằng lại nền da\nThường sử dụng cho làn da sau peel \nLấy nhân mụn sạch và kết hợp dưỡng chất vùng dòng nước xoáy theo công nghệ vortex để làm sạch từng lỗ chân lông\nCá nhân hoá liệu trình chăm sóc da dựa vào đa dạng các ống ampoule tinh chất \nChỉ định: Chuẩn bị nền da trước khi vào treatment/ peel", "• Cơ chế: máy detox dòng nước xoáy (vortex) kết hợp dung dịch Detox 1-2-3 hút sạch bã nhờn, nhân mụn li ti, đồng thời truyền ampoule dưỡng chất theo nhu cầu → mặt nạ Mona Frema làm dịu.\n• Chỉ định thêm: da dầu bí bách, lỗ chân lông chứa nhiều bã, da tiếp xúc khói bụi, da xỉn; chuẩn bị nền 3–7 ngày trước peel/meso/phi kim.\n• Hạn chế: da đang bong tróc mạnh, vết thương hở.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: dùng lực xoáy hút Vortex làm sạch sâu từng lỗ chân lông, hút bã nhờn và nhân mụn li ti, đồng thời truyền tinh chất – sau đó cân bằng lại da; da sạch thoáng, sẵn sàng hấp thu các liệu trình điều trị.\n③ Uy tín: tẩy trang Dermedic (Ba Lan), phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["80db4f4d-ecdc-4e79-a3ba-3a047a8b5c73", "Làm sạch sâu, nới lòng tế bào sừng bằng enzyme\nPhù hợp da mụn đỏ, viêm sẩn đỏ, da yếu chưa thể peel\nCân bằng hệ khuẩn cho da\nLàm dịu da\nChỉ định: Xử lý nhân mụn và phục hồi da sau peel", "• Cơ chế: enzyme phân giải liên kết tế bào sừng (tẩy da chết sinh học, không cồn/acid mạnh) → cà da ion làm sạch sâu → lấy nhân mụn → mặt nạ bột kháng viêm → điện di Transamin (tranexamic acid) làm dịu, giảm đỏ, ngăn thâm.\n• Chỉ định thêm: da mụn đỏ, hồng ban sau mụn (PIE), da nhạy cảm/da mỏng chưa đủ khoẻ để peel, da sau peel cần làm sạch nhẹ nhàng, da có nguy cơ thâm sau viêm.\n• Hạn chế: dị ứng enzyme, da trầy xước.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: enzyme phân giải lớp sừng già một cách dịu nhẹ (không acid mạnh), cà da ion làm sạch sâu, điện di Transamin chống đỏ – chống thâm; phù hợp da mụn nhạy cảm, không bong tróc.\n③ Uy tín: tẩy trang Dermedic (Ba Lan), phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["d2de3110-438f-4d0c-8e58-3f8c3f25fc61", "Phù hợp da nhạy cảm thiên dầu\nPhù hợp nhu cầu muốn căng bóng bề mặt\nMở cổ nang lông, detox giúp da sạch", "• Cơ chế: DMK Enzyme số 2 tạo màng co kéo, ‘bơm’ tuần hoàn bạch huyết, đẩy độc tố & dịch ứ ra ngoài; Aqua Herb hydrat hoá, làm dịu → da săn, mở cổ nang lông, căng bóng.\n• Chỉ định thêm: da nhạy cảm thiên dầu, da phù nề/bọng mặt, da xỉn mệt mỏi, da sau mụn cần làm khoẻ; dùng trước sự kiện để da căng.\n• Hạn chế: rosacea đang bùng phát mạnh, giãn mao mạch nặng (cảm giác nóng/căng khi ủ enzyme).", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: enzyme DMK tạo lực co kéo kích thích hệ bạch huyết, đẩy độc tố và dịch ứ ra ngoài – mặt gọn, da săn và căng bóng ngay; trong lúc ủ sẽ thấy căng kéo, nhói nhẹ là enzyme đang hoạt động.\n③ Uy tín: DMK (Úc) – liệu pháp enzyme nổi tiếng thế giới; phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["f524e7eb-e7cb-4054-a711-e6d1ba4fa169", "Chăm sóc da cơ bản\nPhù hợp làm thư giãn\nKhách mới muốn thư giãn massage hoặc duy trì đều đặn\nLàn da không có hoặc có ít mụn", "• Cơ chế: Bioderma Sensibio H2O tẩy trang không cồn → Gel Moussant làm sạch dịu → tẩy da chết Dermalogica → massage kem Histolab → mặt nạ bột kháng viêm hút dầu → serum Sebium kiểm soát bã nhờn, hạn chế bít tắc → Atoderm khoá ẩm → Photoderm chống nắng.\n• Chỉ định thêm: da dầu/hỗn hợp thiên dầu ít mụn, lỗ chân lông bít nhẹ, khách muốn chăm sóc định kỳ giá dễ tiếp cận.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: bộ dược mỹ phẩm Bioderma lành tính: làm sạch dịu, massage thư giãn, mặt nạ kháng viêm + serum Sebium kiềm dầu – da sạch, ráo dầu, ít bít tắc.\n③ Uy tín: Bioderma – dược mỹ phẩm Pháp, có mặt tại nhà thuốc trên toàn thế giới."], ["8312fe6a-7ebe-4ad9-82f6-3ab56535cc93", "Chăm sóc da cơ bản\nPhù hợp đối tượng khách hàng có tuổi muốn thư giãn healing\nKhách mới muốn trải nghiệm cảm nhận thư giãn \nLàn da không có quá nhiều vấn đề", "• Cơ chế: làm sạch dịu (Sensibio) → massage Histolab → mặt nạ → serum Sensibio Defensive làm dịu, củng cố hàng rào → Atoderm cấp ẩm, giảm khô ráp → Photoderm.\n• Chỉ định thêm: da khô, da nhạy cảm dễ đỏ, da khách lớn tuổi, da mất nước mùa lạnh.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: bộ Bioderma cho da nhạy cảm: Sensibio làm dịu + Atoderm khoá ẩm, kết hợp massage healing – da mềm ẩm, hết căng rát.\n③ Uy tín: Bioderma – dược mỹ phẩm Pháp dành cho da nhạy cảm."], ["c66ca3a3-d814-4d14-86c9-bce15ee2de73", "Lấy nhân mụn chuyên sâu\nCó các pp hỗ trợ làm dịu da sau lấy mụn\nPhù hợp cho những nền da nhiều mụn, sau peel", "• Cơ chế: làm sạch + xông hơi làm mềm nhân → lấy nhân chuyên sâu → mặt nạ bột kháng viêm → Sebium serum giảm bã nhờn, ngừa mụn tái → dưỡng ẩm + KCN.\n• Chỉ định thêm: mụn ẩn, mụn đầu đen, da dầu mụn nhẹ–trung bình, giai đoạn đẩy mụn.\n• Hạn chế: mụn bọc/viêm nặng → kết hợp Light Therapy/Acne Spot Meso.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: lấy nhân mụn chuyên sâu bằng Acne Tweezer + mặt nạ kháng viêm + Sebium kiểm soát dầu, ngừa mụn tái – da thông thoáng, giảm mụn ẩn.\n③ Uy tín: Bioderma – dược mỹ phẩm Pháp."], ["339a1b0d-4b4a-4704-9b96-c0ddcea20c4c", "Chăm sóc da dầu cơ bản\nKhách cao cấp thích massage thư giãn\nKhách nước ngoài ( châu Âu, Mỹ) muốn làm sạch", "• Cơ chế: phương pháp Biologique Recherche ‘cá nhân hoá theo Skin Instant’: Lait SR làm sạch + welcome massage → Lotion P50 (AHA/PHA + niacinamide) cân bằng pH, làm sạch sừng, điều tiết dầu → lấy mụn → Masque Vivant (chiết xuất men, kẽm) se lỗ chân lông, giảm dầu → Sérum Extraits Tissulaires + Crème Elastine tái tạo, đàn hồi\n• Chỉ định thêm: da dầu lỗ chân lông to, da sần, da hỗn hợp; khách cao cấp, khách nước ngoài quen BR", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: phương pháp Biologique Recherche (Pháp) cá nhân hoá theo tình trạng da: Lotion P50 cân bằng pH, làm sạch sừng + Masque Vivant se khít lỗ chân lông – da ráo dầu, mịn, sáng.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["c233d5c7-1238-4255-9bb2-a9f1d539b171", "Chăm sóc da khô cơ bản\nKhách cao cấp thích massage thư giãn\nKhách nước ngoài ( châu Âu, Mỹ) muốn cấp ẩm", "• Cơ chế: như Basic da dầu nhưng mặt nạ VIP O2 (oxy hoá, thải độc, làm sáng) + serum & Crème Elastine giữ ẩm, tăng đàn hồi\n• Chỉ định thêm: da khô, xỉn, mệt mỏi, da sống ở môi trường ô nhiễm/máy lạnh; da lão hoá sớm", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: Lotion P50 + mặt nạ VIP O2 cung cấp oxy, thải độc, làm sáng; Crème Elastine tăng đàn hồi – da khô xỉn trở nên mềm ẩm, tươi sáng ngay sau buổi.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["34db4dba-ca21-441e-aa74-8346647276f9", "Cấp cứu nền da đang trong tình trạng rát/ đỏ\nLàm dịu da tức thì\nPhục hồi nền da đang bị bong do peel, treatment", "• Cơ chế: xịt L''Eauxygénante → Masque Biosensible + Cryostick (lạnh co mạch, giảm nóng đỏ) → Serum Biosensible làm dịu, phục hồi hàng rào → massage nhẹ\n• Chỉ định thêm: da kích ứng, rát đỏ, da sau peel/laser bong tróc, da nhiễm corticoid giai đoạn dịu, rosacea nhẹ; ‘cấp cứu’ trước sự kiện khi da đang đỏ", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: cấp cứu da kích ứng: xịt khoáng oxy + mặt nạ Biosensible + Cryostick lạnh co mạch – hạ nhiệt, giảm đỏ rát tức thì, phục hồi hàng rào da.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["2dee3058-12ce-4865-851f-1987a47700e6", "Phù hợp với nền da dầu mụn dày sừng\nCó chứa AHA BHA giúp làm sạch các lỗ chân lông\nCân bằng tuyến bã nhờn\nPhù hợp cho các nền da dầu vào mùa hè", "• Cơ chế: Lotion P50 + booster MC110 (AHA/BHA, kẽm…) làm sạch sừng, thông nang lông, kiểm soát bã nhờn → mặt nạ + serum làm dịu\n• Chỉ định thêm: da dầu mụn, dày sừng, lỗ chân lông to, da sần; mùa hè nóng ẩm\n• Hạn chế: da mỏng nhạy cảm, đang bong do treatment", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: booster MC110 làm sạch sừng, thông thoáng nang lông, kiểm soát bã nhờn theo công thức BR – da dầu mụn mịn và ráo dầu rõ rệt.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["b3802162-6997-44cf-98a1-1953b44bb8c9", "Detox làm sạch cho da\nHiệu ứng trắng sáng cho da xỉn màu\nCung cấp oxy cho nền da ở văn phòng liên tục, môi trường đô thị ô nhiễm", "• Cơ chế: opening massage → Lotion P50 → booster + găng VIP O2 tạo môi trường giàu oxy, thải độc, kích thích trao đổi chất → mặt nạ VIP O2 làm sáng\n• Chỉ định thêm: da xỉn, mệt mỏi, người hút thuốc/thức khuya, da văn phòng, da sống trong môi trường ô nhiễm", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: găng tay + booster VIP O2 tạo môi trường giàu oxy, thải độc, kích thích trao đổi chất – da xỉn mệt mỏi hồng hào, tươi sáng như vừa được ‘thở’.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["7d7c52ce-16f9-4472-9a18-543b37e3176c", "Cấp ẩm cho da\nKết quả đạt được như 1 lần mesotherapy căng bóng\nPhù hợp da lão hoá, nhiều nếp nhăn li ti", "• Cơ chế: booster Lissant chứa HA đa phân tử + peptide làm đầy nếp nhăn bề mặt, mask + serum + Crème Elastine tăng đàn hồi → hiệu ứng như 1 lần meso căng bóng nhưng không kim\n• Chỉ định thêm: da lão hoá sớm, nếp nhăn li ti, da khô mất nước, khách sợ kim muốn căng bóng", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: booster Lissant (HA + peptide) làm đầy nếp nhăn bề mặt – hiệu ứng căng bóng như 1 lần meso nhưng không kim, không nghỉ dưỡng.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["d0f52844-f2be-41d8-a7a3-cf687703a68e", "Phù hợp nền da lão hoá dày sừng\nNâng cơ, tạo đường viền khuôn mặt", "• Cơ chế: booster + kỹ thuật massage nâng cơ CVS của BR → kích thích tuần hoàn, săn chắc, định hình đường viền; mask + Crème Elastine tăng đàn hồi\n• Chỉ định thêm: da lão hoá chảy xệ nhẹ, đường viền hàm kém sắc nét, da dày sừng thiếu sức sống", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: kỹ thuật massage nâng cơ CVS độc quyền BR + booster săn chắc – đường viền mặt gọn, da săn và nâng nhẹ ngay sau buổi.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["cae79249-f24a-4282-bbec-7a4039a01b84", "SOS cho làn da đang trong tình trạng nhạy cảm\nDa sau peel trung bình ( TCA)\nDa bị tổn thương hàng rào bảo vệ", "• Cơ chế: Toleskin Set 1 (Cryostick lạnh) + Set 2 – phức hợp làm dịu, giảm viêm, tái lập hàng rào bảo vệ\n• Chỉ định thêm: da nhạy cảm nặng, da sau peel TCA/cắt đáy sẹo/laser, da tổn thương hàng rào, da nhiễm corticoid\n• Lưu ý: cost cao (~46% giá) – cân nhắc bán theo gói hoặc kèm treatment", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: bộ Toleskin + Cryostick làm dịu, giảm viêm, tái lập hàng rào bảo vệ – phục hồi chuyên sâu cho da sau treatment xâm lấn, da lành nhanh, ít thâm.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["5a540be0-8bc8-4c6a-9264-cbb4ce8efdb1", "Tái tạo da, làm sáng da", "• Cơ chế: cocktail hoạt chất tái tạo của BR (chiết xuất mô, vitamin, khoáng) kích thích đổi mới tế bào, làm sáng và mịn bề mặt\n• Chỉ định thêm: da xỉn, thô ráp, lão hoá, da mệt mỏi sau thời gian treatment; tăng cường trước sự kiện", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: cocktail hoạt chất tái tạo của BR kích thích đổi mới tế bào – da mịn màng, sáng rạng rỡ rõ rệt sau buổi đầu.\n③ Uy tín: Biologique Recherche – thương hiệu chăm sóc da cao cấp Paris (Pháp) từ 1978, chỉ có tại spa/clinic được hãng chứng nhận."], ["6624c8be-23f5-476f-a624-24f8683b637e", "Da khoẻ, tiết dầu nhiều\nMụn hỗn hợp với nhiều vấn đề: Mụn viêm, mụn ẩn, thâm đỏ, thâm nâu sau mụn\nThành phần chính: Salicylic, Mandelic, Resortcinol, Azelaic acid, Retinol", "• Cơ chế: Simildiet Degree Lotion hạ pH, làm sạch dầu → peel Inno Recovery (salicylic + mandelic + resorcinol + azelaic + retinol) tác động đa cơ chế: thông nang lông, kháng khuẩn, chống viêm, mờ thâm, tăng tốc đổi mới tế bào.\n• Chỉ định thêm: mụn ẩn + mụn viêm + thâm đỏ/thâm nâu, da dầu dày sừng, lỗ chân lông to.\n• Chống chỉ định: mang thai/cho con bú (retinol, resorcinol), da đang kích ứng, isotretinoin <6 tháng, dị ứng aspirin.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: peel Inno Recovery đa hoạt chất (salicylic, mandelic, azelaic, resorcinol, retinol) xử lý cùng lúc mụn ẩn, mụn viêm, dầu và thâm; có thể bong nhẹ 3–5 ngày.\n③ Uy tín: peel Innoaesthetics – Tây Ban Nha; phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["cb7df33f-67e4-4430-9cd8-063599045043", "Da yếu, mụn đỏ, hồng ban sau viêm\nThành phần chính 1: 8% Ferulico, 5% Malic, 5% Citric, 5% Lactic\nThành phần chính 2: 20% Azelaic Acid, 10% Mandelic Acid", "• Cơ chế: Sesderma Azelac RU – lớp 1 (ferulic 8%, malic, citric, lactic 5%) làm sạch sừng nhẹ, chống oxy hoá; lớp 2 (azelaic 20% + mandelic 10%) kháng khuẩn, chống viêm, giảm đỏ & thâm, an toàn cho da nhạy cảm.\n• Chỉ định thêm: mụn đỏ, hồng ban sau viêm, rosacea thể sẩn mụn, thâm nâu nhẹ, da yếu.\n• Chống chỉ định: da đang trầy xước, dị ứng azelaic.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: peel Sesderma Azelac 2 lớp với Azelaic + Mandelic – kháng khuẩn, giảm đỏ và thâm sau mụn, dịu nhẹ cho da nhạy cảm, ít bong.\n③ Uy tín: Sesderma – Tây Ban Nha; phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["51bddaa0-1c49-4661-a411-24139b691627", "Da mụn yếu, xu hướng mẩn đỏ toàn mặt\nDa yếu, nhiễm corticoid\nDa lộ rõ mao mạch", "• Cơ chế: mặt nạ làm mềm Agrilac (softening mask) làm dịu, cấp ẩm, nới lỏng sừng nhẹ – gần như không bong → massage + Simildiet phục hồi.\n• Chỉ định thêm: da mụn yếu, đỏ toàn mặt, da nhiễm corticoid, lộ mao mạch, da thiếu ẩm; bước chuyển tiếp trước peel mạnh hơn.\n• Chống chỉ định: vết thương hở.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: mặt nạ làm mềm dịu nhẹ, cấp ẩm, nới lỏng sừng – giảm đỏ, làm khoẻ da yếu, không bong; bước đệm trước các peel mạnh hơn.\n③ Uy tín: Simildiet (Tây Ban Nha) chuẩn bị và phục hồi da; chống nắng Heliocare (TBN)."], ["3db82872-d926-43c6-9074-2e7409299cfb", "Da yếu mẩn đỏ. đổ dầu nhiều\nÍt có khả năng bong", "• Cơ chế: Redness Inno thoa bề mặt – phức hợp bảo vệ mạch máu & chống viêm → giảm đỏ, kiểm soát dầu nhẹ, ít bong.\n• Chỉ định thêm: da yếu mẩn đỏ kèm đổ dầu, giãn mao mạch nhẹ, đỏ sau mụn (PIE).\n• Chống chỉ định: vết thương hở.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: Redness Inno thoa bề mặt bảo vệ mạch máu, chống viêm – giảm đỏ, kiểm soát dầu nhẹ, gần như không bong, sinh hoạt bình thường.\n③ Uy tín: Innoaesthetics – Tây Ban Nha; phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["ee6ee647-843b-49cb-bb5d-59442420a229", "Da xỉn màu\nDa thâm sau mụn ( thâm nâu)", "• Cơ chế: Set peel MD Ceutical (acid làm sáng + chất ức chế sắc tố) bong lớp sừng chứa melanin, đều màu da; kết thúc bằng KCN.\n• Chỉ định thêm: da xỉn, thâm nâu sau mụn, sạm nắng, nám nhẹ thượng bì.\n• Chống chỉ định: mang thai, da đang kích ứng.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: set peel MD Ceutical bong lớp sừng chứa sắc tố – da đều màu, mờ thâm nâu sau mụn, sáng mịn hơn sau 1 tuần bong nhẹ.\n③ Uy tín: Simildiet (Tây Ban Nha) chuẩn bị da; chống nắng Heliocare (TBN)."], ["cfacdf31-a0d9-4b95-ab71-bd9cd5fae5c8", "Phù hợp da nhạy cảm, da khô, da lão hoá muốn căng bóng\nKhi peel 2 lớp có khả năng sẽ bong\nThành phần chính: 50% Mandelic Acid, 2% DMAE", "• Phương án PEEL BONG.\n• Cơ chế: Juliette Armand Mandelic 40% (phân tử lớn, thẩm thấu chậm, ít kích ứng; DMAE săn chắc) → bong nhẹ lớp sừng già, da mới mịn, sáng, căng bóng; peel 2 lớp sẽ bong.\n• Chỉ định thêm: da khô/lão hoá muốn thay da nhẹ, da sạm, sần, mụn ẩn nhẹ; da tối màu dễ thâm sau viêm (mandelic an toàn hơn glycolic).\n• Chống chỉ định: da đang kích ứng, vết thương hở.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: Mandelic 40% Juliette Armand – peel có bong: thay lớp sừng già, da mới sáng mịn và căng bóng rõ rệt sau 3–5 ngày bong nhẹ.\n③ Uy tín: Juliette Armand – Hy Lạp (Châu Âu); phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["214500a9-908b-4fea-8400-50477dc32b9a", "Phù hợp da nhạy cảm, da khô, da lão hoá muốn căng bóng\nKhi peel 2 lớp có khả năng sẽ bong\nThành phần chính: 50% Mandelic Acid, 2% DMAE", "• Phương án BÓNG NGAY – KHÔNG BONG.\n• Cơ chế: GiGi Mandelic (mandelic acid) làm sạch sừng bề mặt rất nhẹ, kích thích đổi mới tế bào mà không gây bong → da mịn, sáng, bóng ngay sau buổi.\n• Chỉ định thêm: da nhạy cảm, da khô, khách cần đẹp ngay trước sự kiện/đi làm liền, khách sợ bong; duy trì giữa các đợt điều trị.\n• Chống chỉ định: da đang kích ứng, vết thương hở.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: GiGi Mandelic giúp da căng bóng ngay lập tức nhờ hoạt chất mandelic làm bóng bề mặt mà KHÔNG bong tróc – đi làm, đi tiệc được luôn.\n③ Uy tín: Simildiet (Tây Ban Nha) chuẩn bị da và phục hồi; chống nắng Heliocare (TBN)."], ["575deac6-c306-48b7-b136-cc67242109dd", "Phù hợp da nhạy cảm thiên khô\nPhù hợp nhu cầu muốn căng bóng bề mặt\nKhông sử dụng cho da mụn(tp Lactic)\nThành phần chính: 30% LACTIC ( độ pH 2,5) 15% MANDELIC\nThành phần white peel: kaolin, Lactic, Salicylic, Cheese POwder, Dry Milk powder,  Ypugurt Active", "• Cơ chế: Ahowa white peel (kaolin, lactic, salicylic, bột phô mai/sữa/yogurt active) – lactic cấp ẩm & làm sáng, kaolin hút dầu, men sữa làm dịu → ủ trắng, căng bóng bề mặt.\n• Chỉ định thêm: da khô/nhạy cảm thiên khô, da xỉn, muốn trắng hồng căng bóng nhanh trước sự kiện.\n• Không dùng cho da mụn viêm (lactic có thể gây bít/kích ứng).", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: ủ trắng Ahowa (lactic + men sữa + kaolin) – lactic cấp ẩm và làm sáng, kaolin hút dầu; da trắng hồng, căng bóng ngay sau buổi, rất ít bong.\n③ Uy tín: Simildiet (Tây Ban Nha) chuẩn bị da và phục hồi; chống nắng Heliocare (TBN)."], ["15b7c4e8-aaff-4f82-8a16-4724cfdf4015", "Phù hợp da dày sừng, da khoẻ\nĐổi mới tế bào da trên bề mặt\nXử lý được mụn nhẹ, hồng ban sau viêm, tăng sắc tố sau viêm", "• Cơ chế: Tảo Zena (vi gai sinh học – spicule) tạo vi tổn thương cơ học siêu nhỏ → kích thích bong sừng, đổi mới tế bào, tăng collagen, đẩy mụn; Mona Frema làm dịu.\n• Chỉ định thêm: da dày sừng, sần, lỗ chân lông to, mụn nhẹ, thâm đỏ/thâm nâu sau viêm, sẹo rỗ nông, da lão hoá xỉn.\n• Chống chỉ định: da mỏng, nhạy cảm, đang mụn viêm nặng, mang thai.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: peel vi tảo Zena – vi gai sinh học kích thích thay da tự nhiên, đẩy mụn, tăng collagen; châm chích nhẹ 2–3 ngày, bong mịn 5–7 ngày, da mới sáng mịn.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi; chống nắng Heliocare (TBN)."], ["6884a645-6142-47b6-a22e-fdf085d05c6f", "Chấm và Peel TCA làm đầy sẹo rỗ\nSẹo nặng\nKết hợp cùng cắt đáy sẹo trong 1 buổi", "• Cơ chế: TCA Skintech chấm đáy sẹo (CROSS) + peel TCA toàn vùng → đông vón protein, kích thích collagen mạnh làm đầy sẹo; Simildiet phục hồi.\n• Chỉ định thêm: sẹo rỗ đáy nhọn (ice-pick), sẹo trung bình–nặng; kết hợp cắt đáy sẹo cùng buổi.\n• Chống chỉ định: da tối màu dễ thâm (cần ủ trắng trước), sẹo lồi, mang thai, herpes.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: chấm và peel TCA làm đầy từng sẹo rỗ đáy nhọn, kích thích collagen mạnh; da bong 7–10 ngày, cần nghỉ dưỡng và chống nắng nghiêm ngặt.\n③ Uy tín: TCA Skintech – Tây Ban Nha; Simildiet (TBN)."], ["65b14ba5-1c84-404c-9b55-6e09fc5b11a7", "làm khoẻ da, kích thích hệ bạch huyết\nGiảm tình trạng viêm sưng phù nề", "• Cơ chế: DMK Enzyme 2 tạo màng co kéo → kích thích tuần hoàn, hệ bạch huyết thải độc; Cryo Pro X làm lạnh dịu; Enbioment Serum (cân bằng hệ vi sinh) + Beta Gel (beta-glucan phục hồi) + Herbal Pigment Oil (làm sáng) + Aqua Herb.\n• Chỉ định thêm: da phù nề, xỉn, da mụn đỏ cần làm khoẻ, da nhạy cảm, da sau treatment; nâng săn nhẹ.\n• Hạn chế: giãn mao mạch nặng.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: enzyme DMK tạo lực co kéo kích thích hệ bạch huyết thải độc, không bào mòn da; Cryo Pro X làm lạnh dịu – da khoẻ, săn, sáng, căng kéo rõ ngay sau buổi.\n③ Uy tín: DMK – Úc, liệu pháp enzyme nổi tiếng thế giới; chống nắng Heliocare (TBN)."], ["1dc80dfd-8358-4395-bca0-a4d21ed8878d", "Da khoẻ tiết dầu nhiều\nMụn ẩn, mụn viêm nhẹ\nThành phần chính: BHA, Retinol", "• Cơ chế: DMK Quickpeel (BHA + retinol) làm sạch nang lông, giảm bã nhờn, đẩy nhanh đổi mới tế bào (‘lửa’) → Cryo Pro X làm lạnh dịu (‘băng’) → bộ serum DMK phục hồi, làm sáng.\n• Chỉ định thêm: da dầu, mụn ẩn, mụn viêm nhẹ, lỗ chân lông to, da dày sừng, thâm nhẹ.\n• Chống chỉ định: mang thai (retinol), da mỏng nhạy cảm.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: ‘lửa và băng’: DMK Quickpeel (BHA + retinol) làm sạch sâu nang lông, đẩy nhanh tái tạo, sau đó Cryo Pro X làm lạnh dịu ngay – sạch mụn ẩn, mịn da.\n③ Uy tín: DMK – Úc; Simildiet & Heliocare (Tây Ban Nha)."], ["c46d1954-a1b8-42d2-9d05-d245ac9d606c", "Meso vào từng điểm sắc tố\nPhù hợp cho vùng da nám như bớt hori hoặc ná mảng\nNên sử dụng với PP meso bằng tay \nDa sau thâm mụn", "• Cơ chế: meso tay kim 34G đưa cocktail làm sáng Mesoestetic trực tiếp vào từng điểm sắc tố → ức chế tạo melanin tại chỗ; Dermalux (đèn đỏ/NIR) giảm viêm, tăng tốc lành; Mask LXR + Simildiet làm dịu.\n• Chỉ định thêm: đốm nâu, tàn nhang, thâm sau mụn lâu năm, nám điểm/nám Hori, đốm nâu do nắng.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: meso tay kim 34G đưa tinh chất làm sáng Mesoestetic vào đúng từng đốm sắc tố – xử lý nhắm đích đốm nâu, nám, thâm lâu năm; chiếu đèn Dermalux giúp da lành nhanh.\n③ Uy tín: Mesoestetic – hãng mesotherapy hàng đầu Tây Ban Nha; Simildiet (TBN); đèn Dermalux (Anh)."], ["6d029a51-f096-4043-8f9c-27907fe84c4a", "Meso căng bóng da, làm dày nếp nhăn nông\nSử dụng meso căng bóng trước khi bước vào các giai đoạn meso làm sáng\nNên sử dụng PP meso bằng máy", "• Cơ chế: Mesogun đưa Lapuroon (PDRN + HA + peptide) đều toàn mặt → cấp ẩm sâu, PDRN kích thích tái tạo, tăng collagen/elastin → da căng bóng, đều màu, nếp nhăn nông mờ dần.\n• Chỉ định thêm: da khô thiếu ẩm, da xỉn mệt mỏi, lỗ chân lông to do mất nước, da sau mụn cần phục hồi, chuẩn bị nền trước meso làm sáng.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: Mesogun bắn đều tinh chất Lapuroon (PDRN từ DNA cá hồi + HA + peptide) vào lớp trung bì – cấp ẩm sâu, tái tạo, da căng mọng bóng khoẻ sau 3–5 ngày.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi sau meso; đèn LED Dermalux (Anh)."], ["a1525a36-b44d-4ff6-a83e-09ad2e8d3313", "Meso giúp giảm đỏ, phục hồi da sau cort, sau treatment\nLàm dày nền da, mờ những nếp nhăn liti\nChống chỉ định meso trên nền da mụn yếu\nNên sử dụng PP meso bằng máy", "• Cơ chế: meso tay Redness Inno (phức hợp bảo vệ mạch máu, chống viêm) → giảm đỏ, củng cố thành mạch; Dermalux đèn đỏ hỗ trợ phục hồi; làm dày nền da, mờ nếp nhăn li ti.\n• Chỉ định thêm: da nhiễm corticoid, giãn mao mạch, ửng đỏ dai dẳng, rosacea giai đoạn ổn định, da mỏng sau treatment.\n• Chống chỉ định: nền da mụn viêm yếu; mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: meso tay Redness Inno bảo vệ thành mạch, chống viêm – giảm đỏ, làm dày nền da mỏng yếu, phục hồi da nhiễm corticoid; nền tảng trước khi làm sáng.\n③ Uy tín: Innoaesthetics – Tây Ban Nha; Simildiet (TBN); đèn Dermalux (Anh)."], ["d87031a7-e75a-467d-9986-e71e52b1352a", "Meso làm sáng nâng tone da, ức chế sắc tố\nƯu tiên khách hàng có khả năng chịu đau tốt, muốn trắng sáng toàn bề mặt", "• Cơ chế: meso tay toàn mặt cocktail làm sáng Mesoestetic (ức chế tyrosinase, chống oxy hoá) → nâng tone đều màu; Dermalux hỗ trợ.\n• Chỉ định thêm: da xỉn, không đều màu, thâm nâu sau mụn, nám mảng nhẹ, sạm nắng.\n• Ưu tiên: khách chịu đau tốt. Nên có 1–2 buổi Glow Meso trước để nền da đủ ẩm.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: meso tay toàn mặt tinh chất làm sáng Mesoestetic xuống trung bì, ức chế sắc tố từ gốc – nâng tone đều màu, hiệu quả sâu và bền hơn bôi ngoài.\n③ Uy tín: Mesoestetic – hãng mesotherapy hàng đầu Tây Ban Nha; Simildiet (TBN); đèn Dermalux (Anh)."], ["2544d156-145c-4364-a0d2-d25e3436e272", "Thư giãn cơ toàn khuôn mặt giúp trẻ hoá\nKiềm dầu và thu nhỏ lỗ chân lông.", "• Cơ chế: meso tay HA + Botox liều vi điểm ở lớp nông → thư giãn cơ dựng lông & tuyến bã → giảm dầu, se lỗ chân lông, mịn nếp nhăn nông mà không làm cứng biểu cảm; HA cấp ẩm.\n• Chỉ định thêm: lỗ chân lông to, da dầu, nếp nhăn li ti, da mặt kém mịn; ‘glass skin’.\n• Chống chỉ định: bệnh nhược cơ, đang dùng kháng sinh nhóm aminoglycoside; mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: cấy dưỡng chất HA kết hợp Botox liều vi điểm ở lớp nông – se khít lỗ chân lông, giảm dầu, mịn nếp nhăn li ti mà không đơ mặt; hiệu quả 3–4 tháng.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi sau meso."], ["48a16807-7782-4c98-8705-e97e2e0fa278", "Có tính kháng viêm nên phù hợp làn da bị mụn viêm\nKiểm soát tuyến bã nhờn\nNên phục hồi lớp màng bảo vệ da trước khi thực hiện liệu trình", "• Cơ chế: meso tay Facne Fusion (hoạt chất kháng viêm, điều tiết bã nhờn, kháng khuẩn) → giảm mụn viêm, kiểm soát dầu, hỗ trợ mờ thâm; Dermalux hỗ trợ kháng viêm.\n• Chỉ định thêm: mụn viêm rải rác, da dầu mụn tái phát, mụn nội tiết; thâm đỏ sau mụn.\n• Lưu ý: phục hồi hàng rào bảo vệ trước khi làm.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: meso tay Facne Fusion kháng viêm, điều tiết bã nhờn trực tiếp tại vùng mụn – mụn viêm xẹp nhanh, kiểm soát dầu từ gốc, hạn chế mụn tái.\n③ Uy tín: Fusion Meso – Tây Ban Nha, có mặt tại 65+ quốc gia; đèn Dermalux (Anh)."], ["ab2304de-7d22-462f-bf47-4a3670d1d1f3", "Ngăn ngừa tình trạng mụn viêm đang trong giai đoạn cấp sưng và lan rộng\nGom cồi mụn viêm\nXử lý mụn chai, mụn nội tiết", "• Cơ chế: tiêm Facne Fusion trực tiếp vào nốt mụn viêm → kháng viêm tại chỗ, gom cồi, ngăn lan rộng.\n• Chỉ định thêm: mụn bọc, mụn viêm cấp sưng đau, mụn chai, mụn nội tiết vùng cằm; ‘chữa cháy’ trước sự kiện.\n• Hạn chế: mụn mủ đã vỡ, nhiễm trùng lan rộng (chuyển khám da liễu).", "• Điểm chính: tiêm Facne Fusion trực tiếp vào từng nốt mụn viêm – kháng viêm tại chỗ, gom cồi, giảm sưng đau sau 24–48h, hạn chế thâm sẹo.\n• Uy tín: Fusion Meso – Tây Ban Nha, có mặt tại 65+ quốc gia."], ["9f507c7b-ec1c-4be9-95a7-338eb5b9f33b", "Meso căng bóng da, làm dày nếp nhăn nông\nSử dụng meso căng bóng trước khi bước vào các giai đoạn meso làm sáng\nNên sử dụng PP meso bằng máy", "• Cơ chế: Mesogun đưa Medisepte Gel Bio (phức hợp sinh học – biocomplex) → cấp ẩm, kích thích tái tạo, làm dày nền da, căng bóng.\n• Chỉ định thêm: da khô, lão hoá sớm, nếp nhăn nông, da xỉn thiếu sức sống; nền trước meso làm sáng.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: Mesogun đưa Medisepte Gel Bio (phức hợp sinh học) – cấp ẩm, tái tạo, làm dày nền da; căng bóng bền hơn bản Glow Meso.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi sau meso."], ["04a82017-7d55-4d06-98f9-c1de06b080a8", "Meso căng bóng da, làm dày nếp nhăn nông\nSử dụng meso căng bóng trước khi bước vào các giai đoạn meso làm sáng\nNên sử dụng PP meso bằng máy", "• Cơ chế: Mesogun đưa Teoxane Redensity 1 (HA không liên kết chéo + 8 amino acid, 3 chất chống oxy hoá, 2 khoáng chất, vitamin B6) → bù ẩm sâu, kích thích collagen, tăng mật độ da.\n• Chỉ định thêm: da lão hoá 30+, nếp nhăn nông, da mỏng xỉn, da khô mất đàn hồi.\n• Lưu ý: cost cao (~34% giá NY).\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: Mesogun đưa Teoxane Redensity 1 (HA + 8 amino acid + chống oxy hoá + vitamin B6, Thuỵ Sĩ) – tăng mật độ da, căng mịn tự nhiên, mờ nếp nhăn nông kéo dài.\n③ Uy tín: Teoxane – Thuỵ Sĩ, chuyên gia HA hàng đầu thế giới."], ["23a99607-16fb-40cc-b88b-7243af72f97e", "Da đang trong quá trình điều trị sẹo\nDa tổn thương sau mụn\nChống chỉ định meso trên nền da mụn yếu", "• Cơ chế: meso tay vào vùng sẹo: Fusion Mesomatrix (phức hợp tái tạo nền trung bì) kích thích tăng sinh collagen, làm đầy đáy sẹo + Redness Inno giảm đỏ, chống viêm → Dermalux đèn đỏ tăng tốc lành.\n• Chỉ định thêm: sẹo rỗ nông–trung bình, thâm đỏ sau mụn, da sau cắt đáy sẹo/TCA cần tái tạo; kết hợp MNRF.\n• Chống chỉ định: nền da mụn yếu; mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: meso tay vào vùng sẹo: Fusion Mesomatrix kích thích collagen làm đầy đáy sẹo + Redness Inno giảm đỏ – sẹo nông dần, da lành nhanh; dùng xen kẽ với cắt đáy/MNRF.\n③ Uy tín: Fusion Meso + Innoaesthetics – Tây Ban Nha; đèn Dermalux (Anh)."], ["cd1709ad-1323-4e18-9b04-114e04f20685", "Phi kim thu nhỏ lỗ chân lông. Áp dụng cho nền da tiết nhiều dầu\nKiềm dầu\nHỗ trợ điều trị mụn ẩn", "• Cơ chế: phi kim (đầu kim 12/kim lăn 0.25) tạo vi kênh → Anubis Regul Oil (salicylic, tea tree, witch hazel…) thấm sâu điều tiết bã nhờn, kháng khuẩn → Mask LXR làm dịu.\n• Chỉ định thêm: lỗ chân lông to, da dầu bóng nhờn, mụn ẩn, da sần vùng chữ T.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: phi kim tạo vi kênh đưa tinh chất Anubis Regul Oil (salicylic, tea tree) xuống sâu – điều tiết bã nhờn, se khít lỗ chân lông, giảm mụn ẩn; da ráo dầu rõ sau 2–3 buổi.\n③ Uy tín: Anubis Barcelona – Tây Ban Nha; Simildiet (TBN)."], ["0f7c1e2d-a557-4244-b9a4-d803ebb42751", "Phi kim làm sáng\nNgăn ngừa sắc tố bề mặt\nNám do tăng sinh nội mô mạch máu ( Tranexamic acid)", "• Cơ chế: phi kim + Tranacix (tranexamic acid) ức chế hoạt hoá melanocyte qua con đường plasmin và giảm tăng sinh mạch máu → làm sáng, giảm nám.\n• Chỉ định thêm: nám mạch máu, nám mảng, thâm nâu sau mụn, da sạm không đều màu.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: phi kim đưa Tranexamic acid (Tranacix) – hoạt chất ‘vàng’ trị nám – ức chế sắc tố và giảm tăng sinh mạch máu; da sáng đều màu, mờ nám dần.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi sau phi kim; tẩy trang Dermedic (Ba Lan)."], ["c3cb1b34-23e5-47e2-b8c8-a5760310a111", "Phi kim phục hồi\nDa yếu dễ mẩn đỏ, lộ mao mạch, da sau nhiễm cortidoic, da mỏng do treatment", "• Cơ chế: phi kim nông + Exomage (exosome – tín hiệu tái tạo tế bào) → giảm viêm, phục hồi hàng rào, làm dày nền da.\n• Chỉ định thêm: da yếu dễ đỏ, lộ mao mạch, da nhiễm corticoid, da mỏng do lạm dụng treatment, da sau mụn.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: phi kim nông + Exomage (exosome) truyền tín hiệu tái tạo tế bào – giảm viêm, giảm đỏ, làm dày và khoẻ nền da yếu.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi sau phi kim; tẩy trang Dermedic (Ba Lan)."], ["62cbf8d4-74b0-4ead-867e-3a46132b7d82", "Phi kim cấp ẩm căng bóng tức thì", "• Cơ chế: phi kim + Exomage (exosome) → kích thích tái tạo, giữ nước, da căng bóng tức thì.\n• Chỉ định thêm: da khô, mất nước, xỉn; trước sự kiện; khách muốn căng bóng giá mềm hơn meso.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: phi kim + Exomage (exosome) kích thích tái tạo, giữ nước – da căng bóng tức thì, hồi phục nhanh.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi sau phi kim; tẩy trang Dermedic (Ba Lan)."], ["a4fb7c8b-df21-4160-b2f4-813cbfcad0b7", "", "• Cơ chế: phi kim + Superjection Hyaluronate (HA skin booster) → cấp ẩm sâu, căng mọng → mặt nạ Conapidil làm dịu, khoá dưỡng chất.\n• Chỉ định thêm: da khô, xỉn, lão hoá sớm, nếp nhăn mất nước; trước sự kiện.\n• Lưu ý: dùng hết hàng thì cắt mã (cùng Renew Fest).\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, đang dùng isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: phi kim + skin booster Superjection Hyaluronate cấp ẩm sâu, mặt nạ Conapidil khoá dưỡng chất – da mọng nước, bóng khoẻ kéo dài.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi sau phi kim."], ["93b5bb73-d59e-4928-bb79-e85451942ebd", "", "• Cơ chế: cùng sản phẩm với Glow Fest (Superjection + Conapidil).\n• Lưu ý: dùng hết hàng thì cắt mã.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: như Glow Fest: phi kim + Superjection Hyaluronate + mặt nạ Conapidil – cấp ẩm sâu, da căng mọng; ưu tiên bán hết hàng.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi sau phi kim."], ["744fcbc8-ac61-4fef-8c09-1915b82a0c50", "Da có lỗ chân lông to do lão hoá\nDa có sẹo rỗ", "• Cơ chế: vi kim RF xâm lấn đưa nhiệt vào trung bì → co rút & tái cấu trúc collagen, se lỗ chân lông, làm đầy sẹo → Dermalux đèn đỏ giảm viêm → Mask LXR + Simildiet phục hồi.\n• Chỉ định thêm: sẹo rỗ, lỗ chân lông to do lão hoá, da chùng nhẹ, nếp nhăn nông, da sần.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, isotretinoin (<6 tháng), cơ địa sẹo lồi, máy tạo nhịp/kim loại cấy vùng mặt.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: vi kim RF đưa nhiệt vào trung bì tái cấu trúc collagen – sẹo rỗ đầy dần, lỗ chân lông se khít; da đỏ nhẹ 1–3 ngày.\n③ Uy tín: Simildiet (Tây Ban Nha) phục hồi; đèn LED Dermalux (Anh)."], ["a34fe34f-a049-446f-8588-58afe0a41d5c", "Tác động lớp gai và lớp hạt, kích thích tăng sinh HA tự thân\nDa lão hoá, da khô\nCó hiệu ứng căng bóng", "• Cơ chế: RF không xâm lấn tác động lớp gai & lớp hạt → kích thích tăng sinh HA tự thân, săn da; gel CPU dẫn sóng; Mona Frema làm dịu.\n• Chỉ định thêm: da lão hoá sớm, khô, thiếu sức sống, cần căng bóng không nghỉ dưỡng; duy trì giữa các buổi MNRF/HIFU.\n• Chống chỉ định: máy tạo nhịp, mang thai, kim loại cấy vùng mặt.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: RF không xâm lấn tác động lớp gai và lớp hạt, kích thích da tự sinh HA – căng bóng tự nhiên, không đau, không nghỉ dưỡng.\n③ Uy tín: Phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["0604f280-9eb0-4bdd-a014-f01720441cb7", "", "• Cơ chế: RF không xâm lấn kích thích collagen + DMK Enzyme 2 & Aqua Herb kích thích dẫn lưu bạch huyết → Cryo Pro X làm lạnh → serum DMK phục hồi, làm sáng.\n• Chỉ định thêm: mặt phù nề, bọng, da xỉn mệt mỏi, đường viền kém sắc nét; da sau mụn cần khoẻ.\n• Chống chỉ định: máy tạo nhịp, mang thai.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: sóng RF kích collagen kết hợp enzyme DMK dẫn lưu bạch huyết – mặt gọn, săn, giảm phù nề và sáng da ngay sau buổi.\n③ Uy tín: DMK – Úc, liệu pháp enzyme nổi tiếng thế giới; phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["fc9d856e-0b1a-44f4-b313-76786d0ed4bf", "Da bắt đầu lão hoá\nDa lạm dụng Filler\nDuy trì sau Hifu\nNên lặp lại 3-6 tháng / lần", "• Cơ chế: MPT booster phát năng lượng hội tụ tác động lớp trung bì → kích thích collagen, săn chắc; Mona Frema làm dịu.\n• Chỉ định thêm: da bắt đầu lão hoá, chảy xệ nhẹ, da lạm dụng filler, duy trì sau HIFU, nếp nhăn nông.\n• Chống chỉ định: mang thai, máy tạo nhịp, mới tiêm filler/botox <2 tuần vùng điều trị, bệnh da vùng làm.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: năng lượng MPT hội tụ tác động trung bì, kích thích collagen – săn da, nâng cơ nhẹ, không nghỉ dưỡng; hiệu quả tăng dần sau 1–3 tháng.\n③ Uy tín: Phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["6e65ba5a-e9a9-4ae8-94e8-86985f9fdb39", "Chống và điều trị lão hoá cho vùng cổ", "• Cơ chế: MPT booster vùng cổ 80–100 shots kích thích collagen, giảm nếp nhăn ngang cổ, săn da; Mona Frema làm dịu; Simildiet Post Treatment phục hồi, khoá ẩm.\n• Chỉ định thêm: nếp nhăn cổ, da cổ chùng, cổ sạm.\n• Chống chỉ định: mang thai, máy tạo nhịp, bệnh tuyến giáp chưa ổn định, bệnh da vùng cổ.", "Điểm chính: MPT 80–100 shots vùng cổ kích thích collagen – mờ ngấn cổ, da cổ săn chắc; kết thúc bằng Simildiet phục hồi."], ["d1de7d62-0011-4a3c-9138-4d8a35b44357", "Da lão hoá chảy xệ\nNọng cằm nhiều\nXuất hiện rãnh cười do khối mỡ má đổ", "• Cơ chế: HIFU (siêu âm hội tụ cường độ cao) tác động tới lớp SMAS & mỡ dưới da → co rút, nâng cơ, giảm mỡ nọng, kích collagen kéo dài; Mask LXR làm dịu → Simildiet Post Treatment phục hồi → KCN Neoretin/Heliocare.\n• Chỉ định thêm: chảy xệ, nọng cằm, rãnh cười do mỡ má đổ, đường viền hàm kém sắc nét.\n• Chống chỉ định: mang thai, máy tạo nhịp, mới tiêm filler/chỉ <1 tháng, mặt quá gầy, mụn viêm vùng làm.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: HIFU hội tụ siêu âm tới lớp SMAS và mỡ dưới da – nâng cơ không phẫu thuật, gọn nọng cằm, giảm rãnh cười; hiệu quả rõ sau 1–3 tháng, duy trì 12–18 tháng.\n③ Uy tín: Phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["dbc2df92-202c-4307-a4c5-42cd63223b28", "Sẹo rỗ\nThích hợp nhất cho sẹo đáy vuông, đáy tròn\nLỗ chân lông to lâu năm", "• Cơ chế: ủ tê → cắt đáy sẹo bằng kim 27G (subcision) phá dải xơ kéo đáy sẹo → cà bề mặt sẹo bằng dao 11/12 → lăn kim 2.0 tạo vi tổn thương kích collagen → chấm TCA (Aktivator 50%) cho sẹo đáy nhọn → peel TCA Skintech + Retinol Neostrata tái tạo bề mặt → Simildiet phục hồi.\n• Chỉ định thêm: sẹo rỗ đáy vuông/đáy tròn/đáy nhọn, sẹo lâu năm, lỗ chân lông to lâu năm.\n• Chống chỉ định: mang thai/cho con bú, da đang viêm nhiễm/herpes/vết thương hở, rối loạn đông máu, isotretinoin (<6 tháng), cơ địa sẹo lồi.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: phác đồ phối hợp: cắt đáy sẹo bằng kim 27G giải phóng dải xơ kéo đáy sẹo, cà bề mặt, lăn kim 2.0 kích collagen, chấm TCA cho sẹo đáy nhọn – xử lý đúng từng loại sẹo.\n③ Uy tín: TCA Skintech & Simildiet – Tây Ban Nha."], ["cb251fb3-8abe-4400-856e-09824748b456", "Điều trị mụn viêm\nÁnh sáng sinh học kết hợp hoạt chất PDT trong điều trị Pacnes gây mụn\nHoạt chất PDT kết hợp ánh sáng xanh trong điều trị mụn\nPDT (Photodynamic Therapy) – Liệu pháp quang động học là phương pháp điều trị mụn bằng cách sử dụng một chất cảm quang (photosensitizer) kết hợp với ánh sáng có bước sóng phù hợp để tiêu diệt vi khuẩn gây mụn, giảm viêm và kiểm soát bã nhờn.\n\nCơ chế hoạt động của PDT kết hợp ánh sáng xanh trong điều trị mụn:\n✅ Bôi hoạt chất cảm quang (Photosensitizer):  5-ALA (5-Aminolevulinic Acid) . Hoạt chất này thẩm thấu vào tuyến bã nhờn và vi khuẩn gây mụn (P. acnes).\n✅  Chiếu ánh sáng xanh (Dermalux Blue Light - 415nm): \n- Ánh sáng xanh kích hoạt hoạt chất cảm quang, tạo ra oxygen singlet (O¹) – một dạng oxy hoạt hóa mạnh.\n- Oxy này tiêu diệt vi khuẩn P. acnes và giảm viêm.\n- Đồng thời, ánh sáng xanh còn giúp kiểm soát dầu nhờn, giảm kích thước tuyến bã.\n\n\nƯu điểm của PDT với ánh sáng xanh trong điều trị mụn:\n✅ Hiệu quả cao: Giảm vi khuẩn gây mụn, giảm viêm mà không cần dùng kháng sinh.\n✅ Không gây kháng thuốc: Khác với kháng sinh uống hoặc bôi, vi khuẩn không thể kháng lại phương pháp này.\n✅ Giảm bã nhờn: Kiểm soát tuyến dầu, giúp giảm tái phát mụn.\n✅ Không xâm lấn: Không cần tiêm hay xâm nhập vào da.\n\nNhược điểm cần lưu ý:\n⚠️ Có thể gây kích ứng tạm thời: Đỏ, bong da nhẹ sau điều trị.\n⚠️ Cần tránh ánh nắng sau điều trị: Vì da nhạy cảm với ánh sáng sau khi bôi hoạt chất PDT.\n\n👉 Ứng dụng thực tế:\n\nPDT ánh sáng xanh phù hợp với mụn viêm, mụn bọc, mụn mủ, đặc biệt là những trường hợp mụn kháng thuốc hoặc tái phát liên tục.\nThường kết hợp với các phương pháp khác như peel da hoặc mesotherapy để tối ưu hiệu quả.", "• Cơ chế: PDT Gel (5-ALA – chất cảm quang) thấm vào tuyến bã & vi khuẩn C. acnes → Dermalux ánh sáng xanh 415nm kích hoạt tạo oxy đơn bội tiêu diệt vi khuẩn, giảm viêm, thu nhỏ tuyến bã.\n• Chỉ định thêm: mụn viêm, mụn mủ, mụn bọc, mụn kháng thuốc/tái phát, da dầu nhiều.\n• Chống chỉ định: mang thai, porphyria, đang dùng thuốc nhạy cảm ánh sáng (tetracycline, isotretinoin…), động kinh nhạy ánh sáng.", "① Trước khi bắt đầu: làm sạch và lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau, không để lại thâm.\n② Điểm chính: PDT Gel (5-ALA) thấm vào tuyến bã, ánh sáng xanh Dermalux 415nm kích hoạt diệt vi khuẩn mụn – giảm viêm, giảm dầu, không gây kháng thuốc.\n③ Uy tín: đèn LED Dermalux (Anh); phục hồi Simildiet & chống nắng Heliocare/Neoretin nhập khẩu Tây Ban Nha."], ["46799551-4f67-4379-9190-a24387930327", "Thư giãn vùng mắt , chống mỏi mắt \nLàm dầy vùng da mắt\nCấp ẩm bề mặt cho vùng da mắt", "• Cơ chế: massage tay + dụng cụ với Eyezone Fluid/Gel & Cream → RF làm ấm, kích collagen vùng mắt → Eyezone Patch cấp ẩm, giảm bọng.\n• Chỉ định thêm: mắt mỏi do màn hình, bọng nhẹ, nếp nhăn li ti đuôi mắt, quầng thâm do mệt mỏi.\n• Chống chỉ định: viêm kết mạc, mới phẫu thuật mắt.", "Điểm chính: massage tay + dụng cụ với bộ Eyezone, RF làm ấm vùng mắt kích collagen, đắp Eyezone Patch – mắt thư giãn, bớt mỏi, bớt bọng, sáng hơn ngay."], ["c103c7ae-b67a-486e-992d-ba14527aa601", "Giảm nhăn, giảm bọng mắt\nThư giã vùng da mắt \nLàm sáng da vùng mắt", "• Cơ chế: HIFU đầu nông vùng mắt co rút collagen → giảm nhăn, giảm bọng, nâng nhẹ mí; Eyezone hỗ trợ cấp ẩm.\n• Chỉ định thêm: nếp nhăn đuôi mắt, mí sụp nhẹ, bọng mỡ nhẹ.\n• Chống chỉ định: mới phẫu thuật mắt, cấy ghép vùng mắt, mang thai.", "Điểm chính: HIFU đầu nông vùng mắt co rút collagen – giảm nhăn đuôi mắt, giảm bọng, nâng nhẹ mí, không xâm lấn."], ["006326a9-32c0-4145-ab80-886c4a5edd0d", "Làm sáng quầng thâm mắt do mạch máu hoặc do sắc tố bề mặt", "• Cơ chế: meso tay Inno Meline01 (phức hợp làm sáng) vào vùng quầng thâm → ức chế sắc tố, cải thiện vi tuần hoàn.\n• Chỉ định thêm: quầng thâm nâu (sắc tố), thâm do di truyền, thâm do chà xát.\n• Lưu ý: cost cao (~69% giá NY) – nên xem lại giá hoặc liều dùng.\n• Chống chỉ định: mang thai/cho con bú, viêm nhiễm vùng mắt, rối loạn đông máu.", "• Điểm chính: meso tay Inno Meline01 vào đúng vùng quầng thâm – ức chế sắc tố, cải thiện vi tuần hoàn, vùng mắt sáng dần sau 3–5 buổi.\n• Uy tín: Innoaesthetics – Tây Ban Nha."], ["f358d71b-4467-49c0-bc58-d1d2f2d0dc1b", "Chỉ định cho tình trạng da vùng mắt khô, lão hoá giai đoạn 1", "• Cơ chế: meso tay Lapuroon (PDRN + HA + peptide) vùng mắt → cấp ẩm sâu, PDRN kích thích tái tạo, tăng collagen → da mắt mọng, mờ nhăn mất nước; Eyezone Patch + Fluid khoá ẩm.\n• Chỉ định thêm: da vùng mắt khô, nhăn li ti do thiếu ẩm, lão hoá giai đoạn 1, quầng thâm do da mỏng.\n• Chống chỉ định: mang thai/cho con bú, viêm nhiễm vùng mắt, dị ứng cá hồi (PDRN), rối loạn đông máu.", "Điểm chính: meso tay Lapuroon (PDRN + HA) vùng mắt – cấp ẩm sâu, da mắt căng mọng, mờ nhăn do khô."], ["af11a088-f73a-4c8b-aa54-462be9905743", "Chỉ định cho tình trạng da vùng mắt khô, lão hoá giai đoạn 1", "• Cơ chế: meso tay Jalupro Young Eye (amino acid + HA) → kích thích nguyên bào sợi tạo collagen/elastin, làm dày da mí, mờ nhăn li ti & quầng thâm do da mỏng.\n• Chỉ định thêm: da vùng mắt mỏng, nhăn li ti, thâm do mạch máu lộ.\n• Lưu ý: chỉ định đang trùng với Meso cấp ẩm – nên cập nhật.\n• Chống chỉ định: mang thai/cho con bú, viêm nhiễm vùng mắt, rối loạn đông máu.", "• Điểm chính: meso tay Jalupro Young Eye (amino acid + HA) kích thích collagen – làm dày da mí mỏng, mờ nhăn li ti và thâm do da mỏng.\n• Uy tín: Jalupro – Ý."], ["f4fb63f3-06c9-4930-b5fb-e0fc891934a4", "Làm đầy hốc mắt. Hạn chế quầng thâm do hiệu ứng bóng đổ.", "• Cơ chế: Teoxane Redensity 2 – filler HA chuyên rãnh lệ → làm đầy hốc mắt, giảm bóng đổ gây thâm.\n• Chỉ định thêm: rãnh lệ sâu, mắt trũng mệt mỏi.\n• Bắt buộc bác sĩ thực hiện. Chưa có cost.", "• Điểm chính: filler Teoxane Redensity 2 chuyên rãnh lệ – làm đầy hốc mắt, xoá bóng đổ gây thâm, mắt tươi trẻ ngay; bác sĩ thực hiện.\n• Uy tín: Teoxane – Thuỵ Sĩ."], ["6114e4d9-9972-440e-9524-0518361e52dd", "Thư giãn vùng mắt, lưu thông tuần hoàn \nLàm mờ thâm mắt", "• Block cũ chưa chuẩn hoá: RF dùng DMK Quickpeel, rửa mặt Comfortzone (mã cũ) – cần chuẩn hoá lại như RF Eyezone Care.", "Điểm chính: massage tay + dụng cụ với Eyezone kết hợp làm ấm – thư giãn, lưu thông tuần hoàn, mờ thâm do mệt mỏi."], ["1a58b2d1-c5df-42bd-9108-8eda5b01cc3a", "Làm sáng da, Kiểm soát viêm lỗ chân lông", "• Cơ chế: tẩy tế bào chết Triple Action E254 (silica + glycolic + BHA) → Glycolic Body Peeling 255 bong sừng, thông nang lông → peel vi tảo Zena kích thích đổi mới tế bào, làm sáng đều màu → CPU Azulene Gel làm dịu.\n• Chỉ định thêm: da body xỉn, sạm không đều màu, viêm nang lông, da gà, thâm lưng/mông/đầu gối.\n• Chống chỉ định: da đang cháy nắng, vết thương hở, mang thai.", "Điểm chính: peel body 3 bước: tẩy tế bào chết Triple Action E254 – peel Glycolic 255 – vi tảo Zena; da body sáng, mịn, giảm viêm nang lông sau 2–3 buổi."], ["22202777-2649-46b5-b779-aea864e15f5d", "Làm sáng da, Kiểm soát viêm lỗ chân lông", "• Cơ chế: làm sạch + tẩy da chết nhẹ → CPU Hydra Water bù nước → Azulene Gel làm dịu, hạ nhiệt → kem dưỡng body.\n• Chỉ định thêm: da cháy nắng, rát đỏ sau đi biển, da body mất nước.\n• Lưu ý: chỉ định đang copy chung – nên sửa thành ‘phục hồi da sau đi nắng’.", "Điểm chính: bù nước bằng CPU Hydra Water + mặt nạ Azulene làm dịu, hạ nhiệt – giảm rát đỏ, bong tróc và sạm sau đi nắng."], ["5f1e90fa-2f06-486f-b502-43ec50a280b3", "Làm sáng da, Kiểm soát viêm lỗ chân lông", "• Cơ chế: laser toning phá vỡ sắc tố li ti → Azulene Gel làm dịu → kem dưỡng body.\n• Chỉ định thêm: da body sạm, không đều màu, thâm nách/bẹn/đầu gối.\n• Chống chỉ định: da đang cháy nắng, mang thai, dùng thuốc nhạy cảm ánh sáng.", "Điểm chính: laser toning phá vỡ sắc tố li ti – nâng tone body đều màu, không bong; Azulene Gel làm dịu ngay sau chiếu."], ["e9d30640-64b1-4105-b322-0f3b58dd7858", "Làm sáng da, Kiểm soát viêm lỗ chân lông", "• Cơ chế: Triple Action E254 làm sạch, thông nang lông → lấy nhân mụn → Tảo Zena (vi gai) đổi mới tế bào, đẩy mụn, mờ thâm → CPU Azulene Gel làm dịu.\n• Chỉ định thêm: mụn lưng/ngực/vai, thâm sau mụn body, viêm nang lông.\n• Chống chỉ định: mụn viêm mủ lan rộng, mang thai.", "① Lấy nhân mụn bằng Acne Tweezer – phương pháp lấy mụn hạn chế tổn thương, hạn chế đau.\n② Điểm chính: làm sạch nang lông với Triple Action E254 → lấy nhân mụn → peel vi tảo Zena đẩy mụn, mờ thâm – lưng sạch mụn, mịn sau 3–4 buổi."], ["6263d622-94c7-471c-9067-de5c8a655c66", "Meso chống rụng tóc và kích thích mọc tóc", "• Cơ chế: Genosys HR Matrix làm sạch, sát khuẩn da đầu → phi kim da đầu tạo vi kênh → Skin Genuity Hair (yếu tố tăng trưởng/peptide kích nang tóc) → chiếu đèn tăng tuần hoàn nuôi nang tóc.\n• Chỉ định thêm: rụng tóc nội tiết, rụng sau sinh, rụng do stress/sau ốm, tóc thưa mỏng, hói sớm giai đoạn đầu.\n• Chống chỉ định: viêm da đầu nhiễm trùng, vảy nến da đầu đang bùng phát, mang thai.", "Điểm chính: phi kim da đầu đưa Skin Genuity Hair (yếu tố tăng trưởng) trực tiếp vào nang tóc, chiếu đèn kích thích tuần hoàn – giảm rụng sau 3–4 buổi, tóc con mọc sau 2–3 tháng."], ["18f46a51-04fe-46ae-87f1-50d968fc038b", "Detox da đầu, phục hồi sợi tóc", "• Cơ chế: Oway Pure Biodymic + Zanthoxylum detox, làm sạch bã nhờn & tế bào chết da đầu → gội 2 lần (Micro, Volumn) → mặt nạ Silk n Glow phục hồi sợi tóc → xả Daily.\n• Chỉ định thêm: da đầu dầu, gàu, bết nhanh, ngứa; tóc khô xơ hư tổn do uốn/nhuộm; chuẩn bị trước liệu trình chống rụng.", "• Điểm chính: detox da đầu bằng mỹ phẩm hữu cơ Oway (Ý), gội 2 lần và ủ mặt nạ Silk n Glow – da đầu sạch thoáng, hết bết ngứa, tóc mềm bóng.\n• Uy tín: Oway – mỹ phẩm tóc hữu cơ Ý."], ["1568b602-f7cf-4cdd-8d11-50becec05277", "Gội đầu", "• Cơ chế: gội 2 lần Oway Micro + Volumn, xả Daily.\n• Chỉ định thêm: gội thư giãn, làm sạch.", "• Điểm chính: gội 2 lần Oway Micro + Volumn, xả Daily – sạch, thoải mái thư giãn; gợi ý nâng lên Bioscalp Reset khi da đầu dầu/gàu.\n• Uy tín: Oway – mỹ phẩm tóc hữu cơ Ý."], ["fc24021d-491e-48fe-be71-13eb7306636f", "Phi kim chống rụng tóc và kích thích mọc tóc", "• Cơ chế: Genosys HR Matrix sát khuẩn → phi kim da đầu → Radical (tinh chất chống rụng) → chiếu đèn.\n• Chỉ định thêm: rụng tóc mức nhẹ–trung bình, tóc yếu, khách muốn chi phí thấp hơn bản meso.\n• Chống chỉ định: viêm nhiễm da đầu.", "Điểm chính: phi kim da đầu + tinh chất chống rụng Radical, chiếu đèn – giảm rụng, tóc chắc khoẻ, chi phí mềm hơn bản meso."], ["8ad122fb-33cd-4501-93af-75135c3a9881", "Phi kim chống rụng tóc và kích thích mọc tóc", "• Cơ chế: Genosys HR Matrix sát khuẩn → phi kim da đầu → Benpathen + Biotin (panthenol dưỡng nang & thân tóc, biotin hỗ trợ tạo keratin) → chiếu đèn.\n• Chỉ định thêm: tóc mỏng yếu, gãy rụng, thiếu dưỡng chất, rụng nhẹ.", "Điểm chính: phi kim da đầu + Benpathen + Biotin nuôi dưỡng nang và thân tóc – tóc chắc khoẻ, giảm gãy rụng."], ["303f294a-9314-4bfe-9a27-e15aaad92bd5", "", "Kỹ thuật: ĐIỂM\nSố shots: 300-350 SHOTS\nNăng lượng: 17-18", "Vùng nhỏ, da mỏng: kỹ thuật điểm. Hỏi lịch tẩy/nhổ lông – yêu cầu cạo trước 1 ngày, không nhổ/wax 4 tuần trước. Giải thích: 6 buổi đầu triệt kỹ, lông thưa – mảnh dần."], ["e1c59c7b-3d68-47e7-888d-1782d306f696", "", "Kỹ thuật: ĐIỂM\nSố shots: 100-120 SHOTS\nNăng lượng: 16-18", "Mép: lông tơ mảnh – cần đủ buổi, giải thích lông mảnh đáp ứng chậm hơn. Bán kèm vùng mặt."], ["71ec4131-c04b-436b-b002-03b8260c90fb", "", "Kỹ thuật: ĐIỂM\nSố shots: 300-400 SHOTS\nNăng lượng: 18-20", "Nách: vùng dễ chốt nhất – nhấn mạnh hết thâm do cạo/nhổ. Combo nách + mép/bikini."], ["756a59a5-d5ea-4581-9798-8a4a7b8742d1", "", "Kỹ thuật: TRƯỢT\nSố shots: 1000 SHOTS\nNăng lượng: 24-26", "Tay: kỹ thuật trượt. Dặn tránh nắng, KCN vùng tay giữa các buổi."], ["7924b748-be91-40e8-89b1-97f9ee46872f", "", "Kỹ thuật: TRƯỢT\nSố shots: 1000 SHOTS\nNăng lượng: 24-26", "Chân: kỹ thuật trượt; nếu da sạm/viêm nang lông có thể bán kèm Triple Body Peeling."], ["2054246a-20b8-4a06-b024-1ee6d2cfac64", "", "Kỹ thuật: TRƯỢT/ ĐIỂM\nSố shots: 400-500 SHOTS\nNăng lượng: 45948", "Bikini: vùng nhạy cảm – giải thích riêng tư, năng lượng thấp hơn; vệ sinh sạch trước khi làm."], ["f0d082b7-cff7-434f-ae29-9287e6723b75", "", "Kỹ thuật: \nSố shots: \nNăng lượng:", "Body: tư vấn theo gói tổng, so sánh tiết kiệm với mua lẻ từng vùng."]]'::jsonb) r
 where exists (select 1 from public.services s where s.id = (r->>0)::uuid)
on conflict (service_id) do update
   set indication = excluded.indication, indication_ext = excluded.indication_ext,
       consult_guide = excluded.consult_guide, updated_at = now();

-- Tìm kiếm chung v3 = v2 + liệu trình (tên tiếng Việt / tên tiếng Anh) → mở trang hướng dẫn liệu trình
create or replace function public.staff_search_v3(p_q text)
 returns table(kind text, id uuid, title text, subtitle text,
               capacity text, brand text, list_price numeric, min_price numeric)
 language plpgsql stable security definer set search_path to ''
as $function$
declare
  v_q text := nullif(btrim(coalesce(p_q, '')), '');
begin
  if not public.is_staff() then raise exception 'Chỉ nhân viên dùng được tìm kiếm'; end if;
  if v_q is null or length(v_q) < 2 then return; end if;

  if public.my_role()::text <> 'warehouse' then
    return query
    select 'service'::text, s.id, coalesce(nullif(s.name_en, ''), s.name),
           concat_ws(' · ', case when nullif(s.name_en, '') is not null then s.name end, c.name),
           null::text, null::text, s.price, s.member_price
      from public.services s
      left join public.service_categories c on c.id = s.category_id
     where s.is_active
       and (s.name ilike '%' || v_q || '%' or s.name_en ilike '%' || v_q || '%' or c.name ilike '%' || v_q || '%')
     order by (exists (select 1 from public.service_guides g where g.service_id = s.id)) desc,
              (s.name_en ilike v_q || '%' or s.name ilike v_q || '%') desc, coalesce(s.name_en, s.name)
     limit 8;
  end if;

  return query select * from public.staff_search_v2(p_q);
end $function$;

revoke execute on function public.staff_search_v3(text) from public, anon;
grant execute on function public.staff_search_v3(text) to authenticated;
